UPDATE student
SET last_response_at = CASE
    WHEN last_response_at IS NULL OR last_response_at < #{respondedAt}
        THEN #{respondedAt}
    ELSE last_response_at
END
WHERE id = #{studentId}

UPDATE help_request
SET contact_method = #{contactMethod,jdbcType=VARCHAR}, memo = #{memo,jdbcType=LONGVARCHAR}
WHERE id = #{helpRequestId}
